%% =========================================================
%  CORNER DETECTION: Harris vs Hessian
%  Exercise 1 - Low-level corner detectors comparison
%  =========================================================
%
%  This script implements and compares two corner detectors:
%    1. Harris detector  (structure tensor / second-moment matrix)
%    2. Hessian detector (second-order derivatives matrix)
%
%  Both detectors are then evaluated on:
%    - Stability under image resizing (downscale then upscale)
%    - Robustness against Gaussian blurring


%% =========================================================
%  0. LOAD AND PREPARE IMAGE
%  =========================================================

% Load a reference image (grayscale).
% Replace 'image.png' with your actual image filename.
img_color = imread('image.png');

% Convert to grayscale if needed
if size(img_color, 3) == 3
    img = rgb2gray(img_color);
end

% Work in double precision for numerical accuracy
img = im2double(img);

figure('Name','Original Image','NumberTitle','off');
imshow(img); title('Original Image');


%% =========================================================
%  1. HELPER FUNCTIONS (defined at the bottom of the script)
%  =========================================================
%
%  - harris_detector(img, L, epsilon, thresh)
%      Computes Harris keypoints using the Nobel ratio R response.
%      R = det(M) / (trace(M) + epsilon)
%      where M is the 2x2 structure tensor (Harris matrix) smoothed
%      by a Gaussian window of size L.
%
%  - hessian_detector(img, sigma, thresh)
%      Computes Hessian keypoints.
%      R = det(H) - k * trace(H)^2   (similar to Harris but on H)
%      where H is the 2x2 Hessian matrix built from second-order
%      Gaussian derivatives.
%
%  - detect_local_maxima(R, thresh)
%      Uses imdilate to find local maxima above a threshold.


%% =========================================================
%  2. PARAMETERS
%  =========================================================

L       = 3;        % Gaussian window size (std dev) for averaging / derivatives
epsilon = 1e-6;     % Nobel ratio stability term (avoids division by zero
                    % and suppresses flat regions where trace ≈ 0)
thresh_harris  = 0.0005;   % Response threshold for Harris keypoints
thresh_hessian = 0.0005;   % Response threshold for Hessian keypoints

% Note on epsilon: increasing epsilon penalises corners with a small
% trace (i.e. low gradient energy) and effectively raises the detection
% threshold in low-contrast areas.


%% =========================================================
%  3. DETECT CORNERS ON THE ORIGINAL IMAGE
%  =========================================================

% --- Harris ---
[R_harris,  kp_harris]  = harris_detector (img, L, epsilon, thresh_harris);

% --- Hessian ---
[R_hessian, kp_hessian] = hessian_detector(img, L, thresh_hessian);

% Display both detections side by side
figure('Name','Keypoints on Original Image','NumberTitle','off');

subplot(1,2,1);
imshow(img); hold on;
plot(kp_harris(:,2),  kp_harris(:,1),  'r+', 'MarkerSize', 6, 'LineWidth', 1);
title(sprintf('Harris  –  %d keypoints', size(kp_harris,1)));

subplot(1,2,2);
imshow(img); hold on;
plot(kp_hessian(:,2), kp_hessian(:,1), 'g+', 'MarkerSize', 6, 'LineWidth', 1);
title(sprintf('Hessian  –  %d keypoints', size(kp_hessian,1)));

sgtitle('Corner Detection on Original Image');


%% =========================================================
%  4. STABILITY ANALYSIS: RESIZE DOWN THEN BACK UP
%  =========================================================
%
%  Strategy:
%    (a) Downscale the image by a factor s  →  img_small
%    (b) Detect corners on img_small
%    (c) Upscale the keypoints coordinates by 1/s  to bring them back
%        to the original image coordinate system
%    (d) Compare these "remapped" keypoints with those found directly
%        on the original image
%
%  A stable detector should produce keypoints that survive the
%  round-trip (original → small → rescaled back) without drifting
%  too far from their original positions.

scale_factors = [0.75, 0.5, 0.25];   % downscale ratios to test

% Tolerance (in pixels, in the ORIGINAL image space) to consider
% a remapped keypoint as "matched" to an original one
match_tol = 5;

fprintf('\n===== STABILITY vs RESIZING =====\n');
fprintf('%-8s  %-15s  %-15s  %-15s  %-15s\n', ...
    'Scale','Harris #orig','Harris #small','Hessian #orig','Hessian #small');

% Storage for plotting
stability_harris  = zeros(length(scale_factors),1);
stability_hessian = zeros(length(scale_factors),1);

for i = 1:length(scale_factors)
    s = scale_factors(i);

    % --- Downscale ---
    img_small = imresize(img, s);

    % --- Detect on small image ---
    [~, kp_h_small] = harris_detector (img_small, L, epsilon, thresh_harris);
    [~, kp_e_small] = hessian_detector(img_small, L, thresh_hessian);

    % --- Remap keypoints to original coordinate space ---
    kp_h_remap = kp_h_small / s;   % divide row/col by scale factor
    kp_e_remap = kp_e_small / s;

    % --- Count "stable" matches (nearest-neighbour distance < tol) ---
    matched_h = count_matches(kp_harris,  kp_h_remap, match_tol);
    matched_e = count_matches(kp_hessian, kp_e_remap, match_tol);

    % Stability = fraction of original keypoints that are still found
    % after the downscale/upscale round-trip
    stab_h = matched_h / max(size(kp_harris, 1), 1);
    stab_e = matched_e / max(size(kp_hessian,1), 1);

    stability_harris (i) = stab_h;
    stability_hessian(i) = stab_e;

    fprintf('%-8.2f  %-15d  %-15d  %-15d  %-15d\n', s, ...
        size(kp_harris,1), size(kp_h_small,1), ...
        size(kp_hessian,1), size(kp_e_small,1));

    % --- Visual comparison for this scale ---
    figure('Name', sprintf('Stability – scale %.2f', s), 'NumberTitle','off');

    subplot(2,2,1); imshow(img); hold on;
    plot(kp_harris(:,2), kp_harris(:,1), 'r+','MarkerSize',5,'LineWidth',1);
    title(sprintf('Harris – original (%d kp)', size(kp_harris,1)));

    subplot(2,2,2); imshow(img_small); hold on;
    plot(kp_h_small(:,2), kp_h_small(:,1), 'r+','MarkerSize',5,'LineWidth',1);
    title(sprintf('Harris – scale %.2f (%d kp)', s, size(kp_h_small,1)));

    subplot(2,2,3); imshow(img); hold on;
    plot(kp_hessian(:,2), kp_hessian(:,1), 'g+','MarkerSize',5,'LineWidth',1);
    title(sprintf('Hessian – original (%d kp)', size(kp_hessian,1)));

    subplot(2,2,4); imshow(img_small); hold on;
    plot(kp_e_small(:,2), kp_e_small(:,1), 'g+','MarkerSize',5,'LineWidth',1);
    title(sprintf('Hessian – scale %.2f (%d kp)', s, size(kp_e_small,1)));

    sgtitle(sprintf('Stability test – downscale factor %.2f', s));
end

% --- Stability curve ---
figure('Name','Stability Curve','NumberTitle','off');
plot(scale_factors, stability_harris,  'r-o','LineWidth',2,'DisplayName','Harris');  hold on;
plot(scale_factors, stability_hessian, 'g-s','LineWidth',2,'DisplayName','Hessian');
xlabel('Scale factor'); ylabel('Fraction of matched keypoints');
title('Keypoint Stability vs Downscale Factor');
legend; grid on; ylim([0 1]);
% A curve that stays high (close to 1) means the detector is stable:
% it re-finds the same corners even after a size reduction.


%% =========================================================
%  5. ROBUSTNESS ANALYSIS: BLURRING
%  =========================================================
%
%  Strategy:
%    Apply increasing Gaussian blur to the original image and
%    count how many keypoints are still detected as the image
%    gets blurrier.  A robust detector should maintain a
%    reasonable keypoint count even for moderate blur levels.

blur_sigmas = [0, 0.5, 1, 1.5, 2, 3, 4];   % standard deviations of the blur kernel

n_harris_blur  = zeros(size(blur_sigmas));
n_hessian_blur = zeros(size(blur_sigmas));

fprintf('\n===== ROBUSTNESS vs BLUR =====\n');
fprintf('%-10s  %-15s  %-15s\n', 'Blur sigma','Harris #kp','Hessian #kp');

for i = 1:length(blur_sigmas)
    sig = blur_sigmas(i);

    if sig == 0
        img_blur = img;   % no blur
    else
        img_blur = imgaussfilt(img, sig);
    end

    [~, kp_h_blur] = harris_detector (img_blur, L, epsilon, thresh_harris);
    [~, kp_e_blur] = hessian_detector(img_blur, L, thresh_hessian);

    n_harris_blur (i) = size(kp_h_blur, 1);
    n_hessian_blur(i) = size(kp_e_blur, 1);

    fprintf('%-10.1f  %-15d  %-15d\n', sig, n_harris_blur(i), n_hessian_blur(i));
end

% --- Robustness curve ---
figure('Name','Robustness vs Blur','NumberTitle','off');
plot(blur_sigmas, n_harris_blur,  'r-o','LineWidth',2,'DisplayName','Harris');  hold on;
plot(blur_sigmas, n_hessian_blur, 'g-s','LineWidth',2,'DisplayName','Hessian');
xlabel('Blur \sigma'); ylabel('Number of detected keypoints');
title('Keypoint Count vs Gaussian Blur Level');
legend; grid on;
% A detector that still finds many keypoints at large sigma values
% is considered more robust to blurring.

% --- Visual: blurred image examples ---
figure('Name','Blur examples','NumberTitle','off');
blur_show = [0, 1, 3];
for bi = 1:3
    sig = blur_show(bi);
    img_b = (sig==0)*img + (sig>0)*imgaussfilt(img, sig);
    [~,kp_h_b] = harris_detector (img_b, L, epsilon, thresh_harris);
    [~,kp_e_b] = hessian_detector(img_b, L, thresh_hessian);

    subplot(2,3,bi);
    imshow(img_b); hold on;
    plot(kp_h_b(:,2), kp_h_b(:,1), 'r+','MarkerSize',5);
    title(sprintf('Harris  \sigma=%.1f (%d kp)', sig, size(kp_h_b,1)));

    subplot(2,3,bi+3);
    imshow(img_b); hold on;
    plot(kp_e_b(:,2), kp_e_b(:,1), 'g+','MarkerSize',5);
    title(sprintf('Hessian \sigma=%.1f (%d kp)', sig, size(kp_e_b,1)));
end
sgtitle('Robustness against Gaussian blurring');


%% =========================================================
%  LOCAL FUNCTIONS
%  =========================================================

% ---------------------------------------------------------
% HARRIS DETECTOR
% ---------------------------------------------------------
function [R, keypoints] = harris_detector(img, L, epsilon, thresh)
% harris_detector  –  Harris corner detector using the Nobel ratio.
%
%  Inputs:
%    img     : grayscale double image
%    L       : standard deviation of the Gaussian window (spatial averaging)
%    epsilon : small constant added to the denominator (Nobel ratio stability)
%    thresh  : minimum R value to keep as a keypoint
%
%  Outputs:
%    R         : response map (same size as img)
%    keypoints : Nx2 array of [row, col] coordinates

    % 1. Compute image gradients using Sobel (or Gaussian derivatives)
    %    Ix and Iy are the partial derivatives along x and y.
    [Ix, Iy] = imgradientxy(img, 'sobel');

    % 2. Compute the three components of the structure tensor M:
    %    M = [ Ix^2   Ix*Iy ]
    %        [ Ix*Iy  Iy^2  ]
    %    Each component is averaged over a local Gaussian window.
    Ix2  = imgaussfilt(Ix .* Ix,  L);
    Iy2  = imgaussfilt(Iy .* Iy,  L);
    IxIy = imgaussfilt(Ix .* Iy,  L);

    % 3. Compute the Nobel ratio response:
    %    R = det(M) / (trace(M) + epsilon)
    %      = (Ix2*Iy2 - IxIy^2) / (Ix2 + Iy2 + epsilon)
    %
    %    - High R  →  corner (both eigenvalues large)
    %    - R ≈ 0   →  flat region
    %    - R < 0   →  edge (one eigenvalue dominates)
    detM   = Ix2 .* Iy2 - IxIy .^ 2;
    traceM = Ix2 + Iy2;
    R = detM ./ (traceM + epsilon);

    % 4. Detect local maxima: a pixel is a keypoint if it is the maximum
    %    in its 3x3 neighbourhood and its R value exceeds the threshold.
    keypoints = detect_local_maxima(R, thresh);
end


% ---------------------------------------------------------
% HESSIAN DETECTOR
% ---------------------------------------------------------
function [R, keypoints] = hessian_detector(img, sigma, thresh)
% hessian_detector  –  Hessian-based corner/blob detector.
%
%  Inputs:
%    img   : grayscale double image
%    sigma : standard deviation for the Gaussian second-order derivatives
%    thresh: minimum |R| value to keep as a keypoint
%
%  Outputs:
%    R         : response map (same size as img)
%    keypoints : Nx2 array of [row, col] coordinates
%
%  The Hessian matrix at each pixel is:
%    H = [ Ixx  Ixy ]
%        [ Ixy  Iyy ]
%  where Ixx, Ixy, Iyy are second-order Gaussian derivatives.
%
%  Response formula (Harris-like on the Hessian):
%    R = det(H) - k * trace(H)^2
%    with k = 0.04  (empirical constant, same role as in classic Harris)
%
%  This is sometimes called the "Harris-Hessian" response.
%  det(H) > 0  →  both eigenvalues same sign  →  corner or blob
%  det(H) < 0  →  saddle point (one +, one –)  →  edge-like

    k = 0.04;   % free parameter: increase to suppress edges further

    % Second-order Gaussian derivative filters
    % We build them by convolving a Gaussian with derivative masks.
    % MATLAB's imgaussfilt only does smoothing, so we differentiate
    % the smoothed image twice.
    img_smooth = imgaussfilt(img, sigma);

    % First derivatives of the smoothed image
    [Ix, Iy] = imgradientxy(img_smooth, 'sobel');

    % Second derivatives  (differentiate again)
    [Ixx, Ixy_x] = imgradientxy(Ix, 'sobel');   % Ixx and mixed (via x)
    [Ixy_y, Iyy] = imgradientxy(Iy, 'sobel');   % mixed (via y) and Iyy

    % Symmetrize the mixed derivative
    Ixy = (Ixy_x + Ixy_y) / 2;

    % Hessian response
    detH   = Ixx .* Iyy - Ixy .^ 2;
    traceH = Ixx + Iyy;
    R = detH - k * traceH .^ 2;

    keypoints = detect_local_maxima(R, thresh);
end


% ---------------------------------------------------------
% LOCAL MAXIMA DETECTION
% ---------------------------------------------------------
function keypoints = detect_local_maxima(R, thresh)
% detect_local_maxima  –  Find pixels that are local maxima above a threshold.
%
%  Uses morphological dilation: a pixel is a local maximum if
%  imdilate(R, H) == R  (i.e. it equals the maximum of its neighbourhood).
%
%  A 3x3 structuring element is used.

    H = strel('square', 3);          % 3x3 neighbourhood
    R_dil = imdilate(R, H);          % each pixel ← max of its 3x3 window

    % A pixel is a local maximum if it equals its dilated value
    % AND it exceeds the threshold
    mask = (R == R_dil) & (R > thresh);

    [rows, cols] = find(mask);
    keypoints = [rows, cols];
end


% ---------------------------------------------------------
% MATCH COUNTING  (for stability analysis)
% ---------------------------------------------------------
function n = count_matches(kp1, kp2, tol)
% count_matches  –  Count how many keypoints in kp1 have at least one
%                   corresponding keypoint in kp2 within distance tol.
%
%  This is a simple nearest-neighbour matching with a distance threshold.
%  Used to quantify how many original keypoints survive the resize round-trip.

    if isempty(kp1) || isempty(kp2)
        n = 0;
        return;
    end

    n = 0;
    for i = 1:size(kp1, 1)
        % Euclidean distances from kp1(i) to all points in kp2
        dists = sqrt( (kp2(:,1) - kp1(i,1)).^2 + (kp2(:,2) - kp1(i,2)).^2 );
        if min(dists) <= tol
            n = n + 1;
        end
    end
end

