%% =========================================================
%  LOCAL FUNCTIONS
%  =========================================================

% ---------------------------------------------------------
% HARRIS DETECTOR
% ---------------------------------------------------------
function [R, keypoints] = harris_detector(img, L, epsilon, thresh)
% harris_detector  –  Harris corner detector using the Nobel ratio.
%
%  Inputs:
%    img     : grayscale double image
%    L       : standard deviation of the Gaussian window (spatial averaging)
%    epsilon : small constant added to the denominator (Nobel ratio stability)
%    thresh  : minimum R value to keep as a keypoint
%
%  Outputs:
%    R         : response map (same size as img)
%    keypoints : Nx2 array of [row, col] coordinates

    % 1. Compute image gradients using Sobel (or Gaussian derivatives)
    %    Ix and Iy are the partial derivatives along x and y.
    [Ix, Iy] = imgradientxy(img, 'sobel');

    % 2. Compute the three components of the structure tensor M:
    %    M = [ Ix^2   Ix*Iy ]
    %        [ Ix*Iy  Iy^2  ]
    %    Each component is averaged over a local Gaussian window.
    Ix2  = imgaussfilt(Ix .* Ix,  L);
    Iy2  = imgaussfilt(Iy .* Iy,  L);
    IxIy = imgaussfilt(Ix .* Iy,  L);

    % 3. Compute the Nobel ratio response:
    %    R = det(M) / (trace(M) + epsilon)
    %      = (Ix2*Iy2 - IxIy^2) / (Ix2 + Iy2 + epsilon)
    %
    %    - High R  →  corner (both eigenvalues large)
    %    - R ≈ 0   →  flat region
    %    - R < 0   →  edge (one eigenvalue dominates)
    detM   = Ix2 .* Iy2 - IxIy .^ 2;
    traceM = Ix2 + Iy2;
    R = detM ./ (traceM + epsilon);

    % 4. Detect local maxima: a pixel is a keypoint if it is the maximum
    %    in its 3x3 neighbourhood and its R value exceeds the threshold.
    keypoints = detect_local_maxima(R, thresh);
end


% ---------------------------------------------------------
% HESSIAN DETECTOR
% ---------------------------------------------------------
function [R, keypoints] = hessian_detector(img, sigma, thresh)
% hessian_detector  –  Hessian-based corner/blob detector.
%
%  Inputs:
%    img   : grayscale double image
%    sigma : standard deviation for the Gaussian second-order derivatives
%    thresh: minimum |R| value to keep as a keypoint
%
%  Outputs:
%    R         : response map (same size as img)
%    keypoints : Nx2 array of [row, col] coordinates
%
%  The Hessian matrix at each pixel is:
%    H = [ Ixx  Ixy ]
%        [ Ixy  Iyy ]
%  where Ixx, Ixy, Iyy are second-order Gaussian derivatives.
%
%  Response formula (Harris-like on the Hessian):
%    R = det(H) - k * trace(H)^2
%    with k = 0.04  (empirical constant, same role as in classic Harris)
%
%  This is sometimes called the "Harris-Hessian" response.
%  det(H) > 0  →  both eigenvalues same sign  →  corner or blob
%  det(H) < 0  →  saddle point (one +, one –)  →  edge-like

    k = 0.04;   % free parameter: increase to suppress edges further

    % Second-order Gaussian derivative filters
    % We build them by convolving a Gaussian with derivative masks.
    % MATLAB's imgaussfilt only does smoothing, so we differentiate
    % the smoothed image twice.
    img_smooth = imgaussfilt(img, sigma);

    % First derivatives of the smoothed image
    [Ix, Iy] = imgradientxy(img_smooth, 'sobel');

    % Second derivatives  (differentiate again)
    [Ixx, Ixy_x] = imgradientxy(Ix, 'sobel');   % Ixx and mixed (via x)
    [Ixy_y, Iyy] = imgradientxy(Iy, 'sobel');   % mixed (via y) and Iyy

    % Symmetrize the mixed derivative
    Ixy = (Ixy_x + Ixy_y) / 2;

    % Hessian response
    detH   = Ixx .* Iyy - Ixy .^ 2;
    traceH = Ixx + Iyy;
    R = detH - k * traceH .^ 2;

    keypoints = detect_local_maxima(R, thresh);
end


% ---------------------------------------------------------
% LOCAL MAXIMA DETECTION
% ---------------------------------------------------------
function keypoints = detect_local_maxima(R, thresh)
% detect_local_maxima  –  Find pixels that are local maxima above a threshold.
%
%  Uses morphological dilation: a pixel is a local maximum if
%  imdilate(R, H) == R  (i.e. it equals the maximum of its neighbourhood).
%
%  A 3x3 structuring element is used.

    H = strel('square', 3);          % 3x3 neighbourhood
    R_dil = imdilate(R, H);          % each pixel ← max of its 3x3 window

    % A pixel is a local maximum if it equals its dilated value
    % AND it exceeds the threshold
    mask = (R == R_dil) & (R > thresh);

    [rows, cols] = find(mask);
    keypoints = [rows, cols];
end


% ---------------------------------------------------------
% MATCH COUNTING  (for stability analysis)
% ---------------------------------------------------------
function n = count_matches(kp1, kp2, tol)
% count_matches  –  Count how many keypoints in kp1 have at least one
%                   corresponding keypoint in kp2 within distance tol.
%
%  This is a simple nearest-neighbour matching with a distance threshold.
%  Used to quantify how many original keypoints survive the resize round-trip.

    if isempty(kp1) || isempty(kp2)
        n = 0;
        return;
    end

    n = 0;
    for i = 1:size(kp1, 1)
        % Euclidean distances from kp1(i) to all points in kp2
        dists = sqrt( (kp2(:,1) - kp1(i,1)).^2 + (kp2(:,2) - kp1(i,2)).^2 );
        if min(dists) <= tol
            n = n + 1;
        end
    end
end
