        \node at (2.25, 1.4) {\small CNN débruiteur};
        \draw[->, thick] (2.25, 1.1) -- (2.25, 0.6);
        \draw[fill=red!30, rounded corners=3pt] (0.2, 0.1) rectangle (4.3, 0.6);
        \node at (2.25, 0.35) {\small \textbf{Échoue sur volumes médicaux}};
      \end{tikzpicture}
  \end{columns}
\end{frame}

% ==================== SECTION 3 ====================
\section{Défis spécifiques au Volumétrique}

\begin{frame}{Pourquoi le volumétrique est différent ?}
  \begin{block}{3 défis fondamentaux}
  \end{block}
  \vspace{0.5em}
  \begin{columns}
    \column{0.32\textwidth}
      \textbf{\textcolor{medblue}{Défi 1 -- Attributs bruités}}\\
      \vspace{0.3em}
      La profondeur et les normales sont \textbf{stochastiques} (dépendent de l'événement de diffusion) : ils sont \emph{eux-mêmes} bruités et ne peuvent pas guider le filtre comme pour les surfaces.

    \column{0.32\textwidth}
      \textbf{\textcolor{medblue}{Défi 2 -- Hétérogénéité}}\\
      \vspace{0.3em}
      Coexistence de \textbf{structures floues} (tissus mous, nuages) et de \textbf{structures denses} (os, vaisseaux) avec reflets spéculaires. Le filtre ne doit pas lisser les détails durs.

    \column{0.32\textwidth}
      \textbf{\textcolor{medblue}{Défi 3 -- Stabilité temporelle}}\\
      \vspace{0.3em}
      Pour la génération vidéo, chaque frame traitée \emph{indépendamment} entraîne des \textbf{artefacts de scintillement} (flickering) très perceptibles.
  \end{columns}

  \vspace{1em}
  \begin{alertblock}{Conséquence}
    Appliquer directement les denoisers existants (OptiX, OIDN) donne de mauvais résultats sur les volumes médicaux : PSNR $\approx 17$--$25$ dB contre $>30$ dB pour leur méthode.
  \end{alertblock}
\end{frame}

\begin{frame}{Le pipeline de rendu volumétrique}
  \begin{block}{Contexte : Cinematic Rendering (Comaniciu et al. 2016)}
    Path tracing volumétrique sur grille voxel 3D avec fonction de transfert RGBA
  \end{block}

  \vspace{0.5em}
  \begin{tikzpicture}[scale=0.85, every node/.style={font=\small}]
    % Steps
    \node[draw, fill=medlightblue, rounded corners, minimum width=2cm, minimum height=0.8cm] (ray) at (0,0) {Lancer de rayon};
    \node[draw, fill=medlightblue, rounded corners, minimum width=2.2cm, minimum height=0.8cm] (march) at (3.5,0) {Ray marching};
    \node[draw, fill=medlightblue, rounded corners, minimum width=2.5cm, minimum height=0.8cm] (scatter) at (7.2,0) {Événement diffusion};
    \node[draw, fill=medlightblue, rounded corners, minimum width=2.2cm, minimum height=0.8cm] (env) at (11,0) {Échant. env. map};

    \draw[->, thick, medblue] (ray) -- (march);
    \draw[->, thick, medblue] (march) -- (scatter);
    \draw[->, thick, medblue] (scatter) -- (env);

    % Annotations
    \node[align=center, text width=2.5cm, text=medred] at (3.5, -1.2) {épaisseur optique suivie};
    \node[align=center, text width=3cm, text=medred] at (7.2, -1.2) {+terme Phong si surface};
    \node[align=center, text width=3cm, text=medred] at (11, -1.2) {\textbf{1000 sppx} pour convergence};
  \end{tikzpicture}

  \vspace{0.8em}
  \begin{columns}
    \column{0.48\textwidth}
      \begin{exampleblock}{Avantage}
        Gestion hybride volumétrique + surfacique $\rightarrow$ rendu naturaliste
      \end{exampleblock}

    \column{0.48\textwidth}
      \begin{alertblock}{Inconvénient}
        Le bruit est très élevé à faible nombre d'échantillons (isotropic phase function, absorption après $N$ rebonds)
      \end{alertblock}
  \end{columns}
\end{frame}

% ==================== SECTION 4 ====================
\section{Solutions Proposées}

\begin{frame}{Solution 1 -- Attributs auxiliaires volumétriques}
  \begin{columns}
    \column{0.52\textwidth}
      \textbf{Attributs primaires} (1\textsuperscript{er} événement de diffusion)
      \begin{itemize}
        \item Position (espace modèle)
        \item Normale (gradient au point)
        \item Albedo (valeur de la fonction de transfert)
        \item \textbf{Caractéristiques volumétriques :}\\
              magnitude du gradient, épaisseur optique, coefficient d'extinction
      \end{itemize}

      \vspace{0.5em}
      \textbf{Attributs secondaires} (2\textsuperscript{e} rebond)
      \begin{itemize}
        \item Couleur après 1\textsuperscript{er} rebond surfacique
        \item Albedo au 2\textsuperscript{e} événement
        \item Caractéristiques volumétriques (1\textsuperscript{er} $\to$ 2\textsuperscript{e} rebond)
      \end{itemize}

    \column{0.45\textwidth}
      \begin{block}{Pourquoi 1 seul échantillon ?}
        \begin{itemize}
          \item Maintenir les temps de rendu courts
          \item Plusieurs échantillons dégradent les attributs (moyenne des positions $\rightarrow$ perte d'information)
        \end{itemize}
      \end{block}

      \begin{alertblock}{Attention}
        Tous ces attributs sont \textbf{eux-mêmes bruités} $\Rightarrow$ architecture réseau dédiée
      \end{alertblock}
  \end{columns}
\end{frame}

\begin{frame}{Solution 2 -- Fonction de perte adaptée}
  \begin{block}{Perte de reconstruction générale}
    \vspace{0.3em}
    \[
      L = 0.8 \cdot L_1 + 0.1 \cdot L_{\text{hfen}} + 0.1 \cdot L_{\text{spec}}
    \]
    \vspace{-0.3em}
  \end{block}

  \begin{columns}
    \column{0.5\textwidth}
      \textbf{Composantes :}
      \begin{itemize}
        \item $L_1$ : erreur absolue pixel-à-pixel
        \item $L_{\text{hfen}}$ : \textit{High Frequency Error Norm}\\
              $\rightarrow$ comparaison des \textbf{gradients} d'image ($\sigma=1.5$)
        \item $L_{\text{spec}}$ : terme \textbf{spéculaire} (nouveau)
        \[
          L_{\text{spec}} = \frac{1}{N}\sum_i \left|\max(0, x_i - \mu_{x_i}) - \max(0, y_i - \mu_{y_i})\right|
        \]
      \end{itemize}

    \column{0.46\textwidth}
      \begin{exampleblock}{Rôle de $L_{\text{spec}}$}
        \begin{itemize}
          \item Isole les highlights en soustrayant la moyenne locale ($11\times11$)
          \item Compense le sous-échantillonnage sévère des reflets (structure hybride diffus/spéculaire)
          \item RMSE : \textbf{0.0279 $\to$ 0.0247} avec $L_{\text{spec}}$
        \end{itemize}
      \end{exampleblock}
  \end{columns}
\end{frame}

\begin{frame}{Solution 3 -- Architecture Double Auto-Encodeur}
  \begin{block}{Principe : diviser pour mieux régner}
    Les attributs secondaires (très bruités) dégradent les performances si traités naïvement
  \end{block}

  \vspace{0.5em}
  \begin{columns}
    \column{0.52\textwidth}
      \begin{tikzpicture}[scale=0.8, font=\small]
        % Primary branch
        \draw[fill=blue!15, rounded corners=4pt] (0, 2.5) rectangle (2.5, 3.2);
        \node at (1.25, 2.85) {\textbf{Réseau primaire}};
        \draw[fill=blue!10, rounded corners=2pt] (0, 1.8) rectangle (2.5, 2.5);
        \node at (1.25, 2.15) {U-Net (attributs prim.)};
        \node[align=center, font=\tiny] at (1.25, 1.5) {Éclairage direct\\haute fréquence};

        % Secondary branch
        \draw[fill=green!15, rounded corners=4pt] (3.5, 2.5) rectangle (6, 3.2);
        \node at (4.75, 2.85) {\textbf{Réseau secondaire}};
        \draw[fill=green!10, rounded corners=2pt] (3.5, 1.8) rectangle (6, 2.5);
        \node at (4.75, 2.15) {U-Net (attributs sec.)};
        \node[align=center, font=\tiny] at (4.75, 1.5) {Éclairage indirect\\basse fréquence};

        % Join
        \draw[->, thick] (2.5, 2.15) -- (3.5, 2.15);
        \node[draw, fill=orange!30, rounded corners=3pt, minimum height=0.6cm, minimum width=1.5cm] at (3, 0.6) {Fusion};
        \draw[->, thick] (1.25, 1.3) -- (1.25, 0.6) -- (2.25, 0.6);
        \draw[->, thick] (4.75, 1.3) -- (4.75, 0.6) -- (3.75, 0.6);
        \draw[->, thick] (3, 0.3) -- (3, -0.2);
        \node at (3, -0.45) {\textbf{Sortie débruitée}};
      \end{tikzpicture}

    \column{0.45\textwidth}
      \textbf{Fonctionnement :}
      \begin{itemize}
        \item Réseau 1 : illumination directe (haute fréquence) via attributs primaires
        \item Réseau 2 : illumination indirecte (basse fréquence) via attributs secondaires \textbf{+ sortie du réseau 1}
        \item Combinaison par \textit{transposed convolution}
      \end{itemize}

      \begin{exampleblock}{Gain}
        Permet d'exploiter des attributs très bruités qui nuiraient dans un réseau unique
      \end{exampleblock}
  \end{columns}
\end{frame}

\begin{frame}{Solution 4 -- Discriminateur Relativiste (GAN)}
  \begin{columns}
    \column{0.5\textwidth}
      \begin{block}{Motivation}
        Les pertes statiques ($L_1$, HFEN) tendent à produire des images floues. Un discriminateur force la génération de \textbf{détails fin visuellement plausibles}.
      \end{block}

      \vspace{0.5em}
      \textbf{Architecture :}
      \begin{itemize}
        \item 5 blocs convolutifs (LeakyReLU + dropout spatial + batch norm)
        \item Convolutions $3\times3$, stride 2, $32 \cdot 2^i$ feature maps
        \item Average pooling final
      \end{itemize}

      \textbf{Perte totale :}
      \[
        L_{\text{total}} = 0.6 \cdot L_d + 0.4 \cdot L_r
      \]

    \column{0.46\textwidth}
      \begin{exampleblock}{Discriminateur relativiste}
        Estime la probabilité que les données \emph{réelles} soient plus réalistes que les données \emph{générées} $\rightarrow$ moins de mises à jour, meilleure qualité.
      \end{exampleblock}

      \begin{alertblock}{Nuance médicale}
        Le GAN peut introduire des détails \textbf{non présents dans la vérité terrain} -- acceptable car l'usage visé est la \textbf{visualisation} (patients, étudiants), pas le diagnostic.
      \end{alertblock}
  \end{columns}
\end{frame}

\begin{frame}{Solution 5 -- Réseau de Reprojection Temporelle}
  \begin{block}{Objectif : cohérence vidéo sans coût de rendu supplémentaire}
    Réutiliser les échantillons des frames précédente et suivante via reprojection
  \end{block}

  \vspace{0.5em}
  \begin{columns}
    \column{0.5\textwidth}
      \textbf{Fonctionnement :}
      \begin{itemize}
        \item Reprojection 2D basée sur la distance au 1\textsuperscript{er} événement de diffusion
        \item 3 frames considérées : $t-1$, $t$, $t+1$
        \item 8 petits auto-encodeurs (1 par canal de features + couleur) pour fusionner les 3 versions
        \item Entraînement \textit{end-to-end} sans verrouillage des encodeurs
      \end{itemize}

    \column{0.46\textwidth}
      \textbf{Défis de la reprojection volumétrique :}
      \begin{alertblock}{}
        \begin{itemize}
          \item Profondeur stochastique $\rightarrow$ jitter même sans mouvement de caméra
          \item Occlusions / désocclusions importantes
          \item Artefacts amplifiés par rapport au cas surfacique
        \end{itemize}
      \end{alertblock}

      \begin{exampleblock}{Résultat}
        Meilleurs SSIM et stabilité temporelle de toutes les architectures testées
      \end{exampleblock}
  \end{columns}
\end{frame}

% ==================== SECTION 5 ====================
\section{Résultats \& Évaluation}

\begin{frame}{Setup expérimental}
  \begin{columns}
    \column{0.48\textwidth}
      \textbf{Données :}
      \begin{itemize}
        \item \textbf{Train :} $\approx$3000 frames, scans CT de patients masculins, fonctions de transfert et env. maps variées
        \item \textbf{Test :} 300 frames, scan CT d'une patiente \textbf{non vue à l'entraînement}
        \item Résolution : $1024 \times 1024$ pixels
        \item GPU : GTX 1070 (consumer-grade)
      \end{itemize}

      \vspace{0.5em}
      \textbf{Métriques :}
      \begin{itemize}
        \item \textbf{PSNR} (pic signal/bruit)
        \item \textbf{SSIM} (similarité structurelle)
        \item \textbf{Stabilité temporelle} ($1 - L_t$)
      \end{itemize}

    \column{0.48\textwidth}
      \textbf{Configurations évaluées :}
      \begin{enumerate}
        \item \textit{Color only} (baseline interne)
        \item \textit{All features} (attributs complets)
        \item \textit{Dual} (double auto-encodeur)
        \item \textit{GAN} (+ discriminateur)
        \item \textit{Reprojection} (+ temporel)
      \end{enumerate}

      \vspace{0.3em}
      \textbf{Baselines externes :}
      \begin{itemize}
        \item OptiX 6.5 (NVIDIA)
        \item Open Image Denoise 1.2 (Intel)
      \end{itemize}
  \end{columns}
\end{frame}

\begin{frame}{Résultats quantitatifs}
  \begin{center}
  \begin{tabular}{lcccc}
    \toprule
    \textbf{Méthode} & \textbf{PSNR} & \textbf{SSIM} & \textbf{Stab. temp.} & \textbf{t/frame} \\
    \midrule
    OptiX (NVIDIA) & 24.72 & 0.806 & 0.9517 & -- \\
    OIDN (Intel) & 17.40 & 0.768 & 0.9727 & -- \\
    \midrule
    Color only & $\sim$29 & 0.87 & 0.979 & 124 ms \\
    All features & $\sim$31 & 0.89 & 0.981 & 131 ms \\
    Dual & $\sim$31.5 & 0.90 & 0.982 & 268 ms \\
    GAN & $\sim$32 & 0.91 & 0.982 & 268 ms \\
    \textbf{Reprojection} & $\sim$28.5 & \textbf{0.92} & \textbf{0.988} & 502 ms \\
    \bottomrule
  \end{tabular}
  \end{center}

  \vspace{0.5em}
  \begin{columns}
    \column{0.48\textwidth}
      \begin{exampleblock}{Points forts}
        \begin{itemize}
          \item Toutes les variantes dominent les baselines industrielles
          \item La reprojection maximise SSIM et stabilité
        \end{itemize}
      \end{exampleblock}

    \column{0.48\textwidth}
      \begin{alertblock}{Nuance reprojection}
        PSNR plus bas car \textbf{bleeding} entre frames (fonctions de transfert changeantes), mais visuellement supérieur en vidéo
      \end{alertblock}
  \end{columns}
\end{frame}

\begin{frame}{Résultats -- Temps de rendu}
  \begin{block}{Gain en temps : accélération de \textbf{185$\times$}}
  \end{block}

  \vspace{0.5em}
  \begin{center}
  \begin{tabular}{lrr}
    \toprule
    \textbf{Pipeline} & \textbf{300 frames} & \textbf{Par frame} \\
    \midrule
    Ground truth (1024 sppx) & 12h 6min & $\sim$2.4 min \\
    \midrule
    Rendu 1 sppx & 1 min 24 s & 0.28 s \\
    + Débruitage Reprojection & 2 min 31 s & 0.50 s \\
    \midrule
    \textbf{Total pipeline débruité} & \textbf{3 min 55 s} & \textbf{0.78 s} \\
    \bottomrule
  \end{tabular}
  \end{center}

  \vspace{0.8em}
  \begin{columns}
    \column{0.48\textwidth}
      \begin{exampleblock}{Contexte hardware}
        Mesures sur GPU \textbf{GTX 1070} (grand public), sans tensor cores, en fp32 -- des GPUs modernes permettraient un gain supplémentaire
      \end{exampleblock}

    \column{0.48\textwidth}
      \begin{block}{Entraînement}
        1000 itérations complètes sur le dataset d'entraînement ; durée variable de \textbf{1 à 5 jours} selon l'architecture
      \end{block}
  \end{columns}
\end{frame}

\begin{frame}{Généralisation}
  \begin{center}
  \begin{tabular}{lcccc}
    \toprule
    \textbf{Scénario} & \textbf{PSNR} & \textbf{SSIM} & \textbf{Stab.} \\
    \midrule
    Dataset d'entraînement & 32.98 & 0.880 & 0.9824 \\
    Scan connu, TF connue & 30.50 & 0.915 & 0.9854 \\
    Scan connu, TF inconnue & 28.66 & 0.840 & 0.9761 \\
    Scan connu, densité uniforme & 32.05 & 0.907 & 0.9868 \\
    Scan inconnu, TF connue & 27.10 & 0.866 & 0.9785 \\
    Scan inconnu, TF inconnue & 24.75 & 0.769 & 0.9643 \\
    \bottomrule
  \end{tabular}
  \end{center}
  \vspace{0.5em}
  \begin{columns}
    \column{0.48\textwidth}
      \begin{exampleblock}{Bonne généralisation}
        Robuste aux nouvelles vues, nouvelles fonctions de transfert, nouvelle anatomie dans une certaine mesure
      \end{exampleblock}

    \column{0.48\textwidth}
      \begin{alertblock}{Limite identifiée}
        Chute notable sur scan \textbf{complètement inconnu} avec TF inconnue $\rightarrow$ dataset d'entraînement plus diversifié nécessaire
      \end{alertblock}
  \end{columns}
\end{frame}

% ==================== SECTION 6 ====================
\section{Limites \& Perspectives}

\begin{frame}{Limites du travail}
  \begin{columns}
    \column{0.5\textwidth}
      \begin{alertblock}{Limites techniques}
        \begin{enumerate}
          \item Architecture conçue pour usage \textbf{offline} (pas temps réel)
          \item Caractéristiques du renderer \textbf{baked-in} (isotropic scattering, etc.)
          \item Propriétés anatomiques universelles potentiellement mémorisées par le réseau
          \item Données d'entraînement limitées aux \textbf{scans CT humains}
        \end{enumerate}
      \end{alertblock}

    \column{0.5\textwidth}
      \begin{block}{Perspectives futures}
        \begin{itemize}
          \item \textbf{Temps réel} via connections récurrentes ou optimisation
          \item \textbf{Sampling adaptatif} couplé au denoiser
          \item Extension à d'autres modalités : vétérinaire, IRM, ultrason
          \item Évaluation de transfert cross-anatomique (haut/bas du corps)
          \item Communication accrue entre sous-réseaux (canaux supplémentaires)
        \end{itemize}
      \end{block}
  \end{columns}
\end{frame}

% ==================== SECTION 7 ====================
\section{Conclusion}

\begin{frame}{Conclusion}
  \begin{block}{Ce que ce papier a apporté}
    Première adaptation réussie du débruitage neural par apprentissage au rendu volumétrique médical
  \end{block}

  \vspace{0.5em}
  \begin{columns}
    \column{0.48\textwidth}
      \textbf{Contributions clés :}
      \begin{itemize}
        \item[\checkmark] Attributs auxiliaires \textbf{spécifiques au volume}
        \item[\checkmark] Perte $L_{\text{spec}}$ pour les \textbf{highlights}
        \item[\checkmark] \textbf{Double auto-encodeur} (direct + indirect)
        \item[\checkmark] \textbf{GAN relativiste} pour la netteté
        \item[\checkmark] \textbf{Reprojection temporelle} pour la vidéo
      \end{itemize}

    \column{0.48\textwidth}
      \begin{exampleblock}{Impact final}
        \begin{itemize}
          \item \textbf{185$\times$} plus rapide que le rendu convergé
          \item Domination des denoisers industriels en contexte volumétrique
          \item Code open-source disponible
        \end{itemize}
      \end{exampleblock}

      \vspace{0.3em}
      \begin{center}
        \texttt{\small github.com/nihofm/ndptmvd}
      \end{center}
  \end{columns}

  \vspace{0.7em}
  \begin{center}
    \large\textbf{Merci pour votre attention !}\\
    \vspace{0.3em}
    \small Questions ?
  \end{center}
\end{frame}

