% ==================== SECTION 1 ====================
\section{Introduction \& Contexte}

\begin{frame}{Contexte : visualisation médicale}
  \begin{columns}
    \column{0.55\textwidth}
      \begin{block}{Le \textit{path tracing} en médecine}
        \begin{itemize}
          \item Données issues de scanners CT (tomographie)
          \item Rendu photoréaliste $\rightarrow$ meilleure perception
          \item Utilisateurs cibles : étudiants, patients, chirurgiens
          \item Applications : éducation médicale, communication médecin-patient, planification opératoire
        \end{itemize}
      \end{block}
      \vspace{0.5em}
