      \end{itemize}

    \column{0.5\textwidth}
      \textbf{Limites}
      \begin{alertblock}{}
        \begin{itemize}
          \item Attributs (profondeur, normales) \textbf{mal définis} en volumétrique
          \item Tendance à \textbf{sur-lisser} les structures fines
          \item Instabilité temporelle difficile à garantir
        \end{itemize}
      \end{alertblock}
      \vspace{0.3em}
      \begin{exampleblock}{Insight clé}
        Les filtres artisanaux ne peuvent pas s'adapter automatiquement à la nature complexe des volumes médicaux
      \end{exampleblock}
  \end{columns}
