\section{Limites \& Perspectives}

\begin{frame}{Limites du travail}
  \begin{columns}
    \column{0.5\textwidth}
      \begin{alertblock}{Limites techniques}
        \begin{enumerate}
          \item Architecture conçue pour usage \textbf{offline} (pas temps réel)
          \item Caractéristiques du renderer \textbf{baked-in} (isotropic scattering, etc.)
          \item Propriétés anatomiques universelles potentiellement mémorisées par le réseau
          \item Données d'entraînement limitées aux \textbf{scans CT humains}
        \end{enumerate}
      \end{alertblock}

    \column{0.5\textwidth}
      \begin{block}{Perspectives futures}
        \begin{itemize}
          \item \textbf{Temps réel} via connections récurrentes ou optimisation
          \item \textbf{Sampling adaptatif} couplé au denoiser
          \item Extension à d'autres modalités : vétérinaire, IRM, ultrason
          \item Évaluation de transfert cross-anatomique (haut/bas du corps)
          \item Communication accrue entre sous-réseaux (canaux supplémentaires)
        \end{itemize}
      \end{block}
  \end{columns}
\end{frame}

