\section{Introduction \& Context}

\begin{frame}{Context: Medical Visualization}
  \begin{columns}
    \column{0.55\textwidth}
      \begin{block}{Path Tracing in Medicine}
        \begin{itemize}
          \item Data from CT scanners (computed tomography)
          \item Photorealistic rendering $\rightarrow$ better perception
          \item Target users: students, patients, surgeons
          \item Applications: medical education, doctor-patient communication, surgery planning
        \end{itemize}
      \end{block}
      \vspace{0.5em}
      \begin{alertblock}{The Core Problem}
        A converged image requires \textbf{$\approx$1000 samples/pixel}\\
        $\Rightarrow$ Several \textbf{minutes per frame}, \textbf{hours for a video}
      \end{alertblock}

    \column{0.42\textwidth}
      \begin{center}
        \begin{tikzpicture}
          \draw[fill=medgray, rounded corners=5pt] (0,0) rectangle (4, 4.5);
