          \node[align=center] at (2, 1.5) {\small\textbf{Neural Network}};
          \draw[->, very thick, medgreen] (2, 1.2) -- (2, 0.6);

          \draw[fill=green!20, rounded corners=3pt] (0.2,0.1) rectangle (3.8, 0.8);
          \node[align=center] at (2, 0.45) {\small\textit{Denoised image}};
        \end{tikzpicture}
      \end{center}
  \end{columns}
\end{frame}

\begin{frame}{Paper Objectives}
  \begin{block}{Research Question}
    Can we transfer neural denoising techniques developed for \emph{surface} rendering to the harder problem of \emph{medical volumetric} rendering?
  \end{block}

  \vspace{1em}
  \begin{columns}
    \column{0.48\textwidth}
      \textbf{Main Contributions:}
      \begin{enumerate}
        \item[\textcolor{medblue}{1.}] Novel \textbf{volumetric auxiliary features}
        \item[\textcolor{medblue}{2.}] \textbf{Loss function} tailored for specular highlights
        \item[\textcolor{medblue}{3.}] \textbf{Dual autoencoder} architecture
        \item[\textcolor{medblue}{4.}] \textbf{Relativistic discriminator} (GAN)
        \item[\textcolor{medblue}{5.}] \textbf{Feature reprojection} for temporal coherence
      \end{enumerate}

    \column{0.48\textwidth}
      \textbf{Key Result:}
      \begin{exampleblock}{}
        \textbf{185$\times$ speedup} over fully converged rendering, using only one rendering pass per pixel.
      \end{exampleblock}
  \end{columns}
\end{frame}

% ==================== SECTION 2 ====================
\section{Related Work}

\begin{frame}{Related Work: Hand-Crafted Filters}
  \begin{columns}
    \column{0.5\textwidth}
      \textbf{Classical Approaches}
      \begin{itemize}
        \item \textbf{À-Trous filters} with auxiliary features (depth, normals, albedo)\\
              \textit{-- Dammertz et al. 2010}
        \item \textbf{Guided filtering}\\
              \textit{-- Bauszat et al. 2011}
        \item \textbf{Non-local means}\\
              \textit{-- Rousselle et al. 2012}
        \item \textbf{SVGF} (Spatiotemporal Variance-Guided Filtering)\\
              \textit{-- Schied et al. 2017}
      \end{itemize}

    \column{0.5\textwidth}
      \textbf{Limitations}
      \begin{alertblock}{}
        \begin{itemize}
          \item Depth and normals \textbf{ill-defined} in volumetric rendering
          \item Tendency to \textbf{over-smooth} fine structures
          \item Temporal stability hard to guarantee
        \end{itemize}
      \end{alertblock}
      \vspace{0.3em}
      \begin{exampleblock}{Key Insight}
        Hand-crafted filters cannot automatically adapt to the complex nature of medical volumes
      \end{exampleblock}
  \end{columns}
\end{frame}

\begin{frame}{Related Work: Learning-Based Denoising}
  \begin{columns}
    \column{0.5\textwidth}
      \textbf{Learning-Based Approaches}
      \begin{itemize}
        \item \textbf{Kernel prediction} via MLP / CNN\\
              \textit{-- Kalantari 2015, Bako 2017}
        \item \textbf{Noise2Noise}: training without clean data\\
              \textit{-- Lehtinen et al. 2018}
        \item \textbf{Recurrent autoencoder} for temporal stability\\
              \textit{-- Chaitanya et al. 2017}
        \item \textbf{Kernel-splatting} for reconstruction fidelity\\
              \textit{-- Gharbi et al. 2019}
        \item Integrated in \textbf{OptiX} (NVIDIA) \& \textbf{OIDN} (Intel)
      \end{itemize}

    \column{0.5\textwidth}
      \textbf{Critical Gap: all of this = surfaces only}
