% ==================== SECTION 3 ====================
\section{Challenges of Volumetric Denoising}

\begin{frame}{Why Is Volumetric Different?}
  \begin{block}{3 Fundamental Challenges}
  \end{block}
  \vspace{0.5em}
  \begin{columns}
    \column{0.32\textwidth}
      \textbf{\textcolor{medblue}{Challenge 1 -- Noisy Features}}\\
      \vspace{0.3em}
      Depth and normals are \textbf{stochastic} (depend on scatter events): they are \emph{themselves} noisy and cannot reliably guide the filter as they would for surfaces.

    \column{0.32\textwidth}
      \textbf{\textcolor{medblue}{Challenge 2 -- Heterogeneity}}\\
      \vspace{0.3em}
      Medical data contains both \textbf{fuzzy, cloud-like} structures (soft tissue) and \textbf{dense} ones (bones, vessels) with sharp specular highlights that must not be blurred.

    \column{0.32\textwidth}
      \textbf{\textcolor{medblue}{Challenge 3 -- Temporal Stability}}\\
      \vspace{0.3em}
      For video generation, independently denoising each frame produces highly \textbf{distracting flickering} artifacts even when individual frames are acceptable.
  \end{columns}

  \vspace{1em}
  \begin{alertblock}{Consequence}
    Applying existing denoisers (OptiX, OIDN) directly gives poor results: PSNR $\approx 17$--$25$ dB vs.\ $>30$ dB with the proposed method.
  \end{alertblock}
\end{frame}

\begin{frame}{The Volumetric Path Tracing Pipeline}
  \begin{block}{Base: Cinematic Rendering (Comaniciu et al. 2016)}
    Volumetric path tracing on a 3D voxel grid with an RGBA transfer function
  \end{block}

  \vspace{0.5em}
  \begin{tikzpicture}[scale=0.85, every node/.style={font=\small}]
    \node[draw, fill=medlightblue, rounded corners, minimum width=2cm, minimum height=0.8cm] (ray) at (0,0) {Ray cast};
