    \node[align=center, text width=3cm, text=medred] at (11, -1.2) {\textbf{1000 sppx} for convergence};
  \end{tikzpicture}

  \vspace{0.8em}
  \begin{columns}
    \column{0.48\textwidth}
      \begin{exampleblock}{Advantage}
        Hybrid volumetric + surface handling $\rightarrow$ naturalistic rendering
      \end{exampleblock}

    \column{0.48\textwidth}
      \begin{alertblock}{Drawback}
        Noise is very high at low sample counts (isotropic phase function, absorption after $N$ bounces)
      \end{alertblock}
  \end{columns}
\end{frame}

% ==================== SECTION 4 ====================
\section{Proposed Solutions}

\begin{frame}{Solution 1 -- Volumetric Auxiliary Features}
  \begin{columns}
    \column{0.52\textwidth}
      \textbf{Primary Features} (1\textsuperscript{st} scatter event)
      \begin{itemize}
        \item Position (model space)
        \item Normal (gradient at scatter point)
        \item Albedo (transfer function value)
        \item \textbf{Volumetric characteristics:}\\
              gradient magnitude, optical thickness, extinction coefficient
      \end{itemize}

      \vspace{0.5em}
      \textbf{Secondary Features} (2\textsuperscript{nd} bounce)
      \begin{itemize}
        \item Color after 1\textsuperscript{st} surface scatter event
        \item Albedo at 2\textsuperscript{nd} scatter point
        \item Volumetric characteristics (1\textsuperscript{st} $\to$ 2\textsuperscript{nd} bounce)
      \end{itemize}

    \column{0.45\textwidth}
      \begin{block}{Why only 1 sample?}
        \begin{itemize}
          \item Keeps rendering times minimal
          \item Averaging multiple samples \textbf{degrades} position and normal features (stochastic averaging)
        \end{itemize}
      \end{block}

      \begin{alertblock}{Key Challenge}
        All these features are \textbf{themselves noisy} $\Rightarrow$ dedicated network architecture required
      \end{alertblock}
  \end{columns}
\end{frame}

\begin{frame}{Solution 2 -- Adapted Loss Function}
  \begin{block}{Reconstruction Loss}
    \vspace{0.3em}
    \[
      L = 0.8 \cdot L_1 + 0.1 \cdot L_{\text{hfen}} + 0.1 \cdot L_{\text{spec}}
    \]
    \vspace{-0.3em}
  \end{block}

  \begin{columns}
    \column{0.5\textwidth}
      \textbf{Components:}
      \begin{itemize}
        \item $L_1$: absolute pixel-wise error
        \item $L_{\text{hfen}}$: \textit{High Frequency Error Norm}\\
              $\rightarrow$ compares image \textbf{gradients} ($\sigma=1.5$)
        \item $L_{\text{spec}}$: \textbf{specular highlight} term (novel)
        \[
          L_{\text{spec}} = \frac{1}{N}\sum_i \left|\max(0, x_i - \mu_{x_i}) - \max(0, y_i - \mu_{y_i})\right|
        \]
      \end{itemize}

    \column{0.46\textwidth}
      \begin{exampleblock}{Role of $L_{\text{spec}}$}
        \begin{itemize}
          \item Isolates highlights by subtracting local mean ($11\times11$ neighborhood)
          \item Compensates severe undersampling of specular reflections (stochastic diffuse/specular alternation)
          \item RMSE: \textbf{0.0279 $\to$ 0.0247} with $L_{\text{spec}}$
        \end{itemize}
      \end{exampleblock}
  \end{columns}
\end{frame}

\begin{frame}{Solution 3 -- Dual Autoencoder Network}
  \begin{block}{Principle: Divide and Conquer}
    Secondary features (very noisy) degrade performance when processed naively in a single network
  \end{block}

  \vspace{0.5em}
  \begin{columns}
    \column{0.52\textwidth}
      \begin{tikzpicture}[scale=0.8, font=\small]
        % Primary branch
        \draw[fill=blue!15, rounded corners=4pt] (0, 2.5) rectangle (2.5, 3.2);
        \node at (1.25, 2.85) {\textbf{Primary Network}};
        \draw[fill=blue!10, rounded corners=2pt] (0, 1.8) rectangle (2.5, 2.5);
        \node at (1.25, 2.15) {U-Net (primary feats.)};
        \node[align=center, font=\tiny] at (1.25, 1.5) {Direct illumination\\high-frequency};

        % Secondary branch
        \draw[fill=green!15, rounded corners=4pt] (3.5, 2.5) rectangle (6, 3.2);
        \node at (4.75, 2.85) {\textbf{Secondary Network}};
        \draw[fill=green!10, rounded corners=2pt] (3.5, 1.8) rectangle (6, 2.5);
        \node at (4.75, 2.15) {U-Net (secondary feats.)};
        \node[align=center, font=\tiny] at (4.75, 1.5) {Indirect illumination\\low-frequency};

        % Join
        \draw[->, thick] (2.5, 2.15) -- (3.5, 2.15);
        \node[draw, fill=orange!30, rounded corners=3pt, minimum height=0.6cm, minimum width=1.5cm] at (3, 0.6) {Merge};
        \draw[->, thick] (1.25, 1.3) -- (1.25, 0.6) -- (2.25, 0.6);
        \draw[->, thick] (4.75, 1.3) -- (4.75, 0.6) -- (3.75, 0.6);
        \draw[->, thick] (3, 0.3) -- (3, -0.2);
        \node at (3, -0.45) {\textbf{Denoised output}};
      \end{tikzpicture}

    \column{0.45\textwidth}
      \textbf{How it works:}
      \begin{itemize}
        \item Network 1: high-frequency direct lighting via primary features
        \item Network 2: low-frequency indirect lighting via secondary features \textbf{+ output of Network 1}
        \item Combined via a transposed convolution layer
      \end{itemize}

      \begin{exampleblock}{Gain}
        Enables exploitation of very noisy secondary features that would harm a single network
      \end{exampleblock}
  \end{columns}
\end{frame}

\begin{frame}{Solution 4 -- Relativistic Discriminator (GAN)}
  \begin{columns}
    \column{0.5\textwidth}
      \begin{block}{Motivation}
        Static losses ($L_1$, HFEN) tend to produce blurry outputs. A discriminator forces the generation of \textbf{visually sharp, plausible details}.
      \end{block}

      \vspace{0.5em}
      \textbf{Architecture:}
      \begin{itemize}
        \item 5 convolutional blocks (LeakyReLU + spatial dropout + batch norm)
        \item $3\times3$ convolutions, stride 2, $32 \cdot 2^i$ feature maps
        \item Average pooling as final layer
      \end{itemize}

      \textbf{Combined loss:}
      \[
        L_{\text{total}} = 0.6 \cdot L_d + 0.4 \cdot L_r
      \]

    \column{0.46\textwidth}
      \begin{exampleblock}{Relativistic Discriminator}
        Estimates the probability that \emph{real} data is more realistic than \emph{generated} data $\rightarrow$ fewer updates needed, higher quality results.
      \end{exampleblock}

      \begin{alertblock}{Medical Nuance}
        GANs may introduce details \textbf{absent from ground truth} -- acceptable here since the use case is \textbf{visualization} (patients, students), not clinical diagnosis.
      \end{alertblock}
  \end{columns}
\end{frame}

\begin{frame}{Solution 5 -- Feature Reprojection Network}
  \begin{block}{Goal: Temporal Coherence Without Extra Rendering Cost}
    Reuse samples from adjacent frames via reprojection
  \end{block}

  \vspace{0.5em}
  \begin{columns}
    \column{0.5\textwidth}
      \textbf{How it works:}
      \begin{itemize}
        \item Reprojection based on distance to 1\textsuperscript{st} scatter event
        \item 3 frames considered: $t-1$, $t$, $t+1$
        \item 8 small autoencoders (one per feature channel + color) to merge the 3 reprojected versions
        \item Trained \textit{end-to-end} without locking encoders
      \end{itemize}

    \column{0.46\textwidth}
      \textbf{Volumetric reprojection challenges:}
      \begin{alertblock}{}
        \begin{itemize}
          \item Stochastic depth $\rightarrow$ jitter even with static camera
          \item More occlusion/disocclusion artifacts than surfaces
          \item Artifacts amplified compared to the surface case
        \end{itemize}
      \end{alertblock}

      \begin{exampleblock}{Result}
        Best SSIM and temporal stability of all tested architectures
      \end{exampleblock}
  \end{columns}
\end{frame}

% ==================== SECTION 5 ====================
\section{Results \& Evaluation}

\begin{frame}{Experimental Setup}
  \begin{columns}
    \column{0.48\textwidth}
      \textbf{Data:}
      \begin{itemize}
        \item \textbf{Train:} $\approx$3000 frames, CT scans of male patients, varied transfer functions and env.\ maps
        \item \textbf{Test:} 300 frames, CT scan of a female patient \textbf{unseen during training}
        \item Resolution: $1024 \times 1024$ pixels
        \item GPU: GTX 1070 (consumer-grade)
      \end{itemize}

      \vspace{0.5em}
      \textbf{Metrics:}
      \begin{itemize}
        \item \textbf{PSNR} (peak signal-to-noise ratio)
        \item \textbf{SSIM} (structural similarity index)
        \item \textbf{Temporal stability} ($1 - L_t$)
      \end{itemize}

    \column{0.48\textwidth}
      \textbf{Evaluated Configurations:}
      \begin{enumerate}
        \item \textit{Color only} (internal baseline)
        \item \textit{All features} (full feature set)
        \item \textit{Dual} (dual autoencoder)
        \item \textit{GAN} (+ discriminator)
        \item \textit{Reprojection} (+ temporal)
      \end{enumerate}

      \vspace{0.3em}
      \textbf{External Baselines:}
      \begin{itemize}
        \item OptiX 6.5 (NVIDIA)
        \item Open Image Denoise 1.2 (Intel)
      \end{itemize}
  \end{columns}
\end{frame}

