  \end{columns}
\end{frame}

\begin{frame}{Generalization}
  \begin{center}
  \begin{tabular}{lccc}
    \toprule
    \textbf{Scenario} & \textbf{PSNR} & \textbf{SSIM} & \textbf{Stab.} \\
    \midrule
    Training set                  & 32.98 & 0.880 & 0.9824 \\
    Known scan, known TF          & 30.50 & 0.915 & 0.9854 \\
    Known scan, unknown TF        & 28.66 & 0.840 & 0.9761 \\
    Known scan, uniform density   & 32.05 & 0.907 & 0.9868 \\
    Unknown scan, known TF        & 27.10 & 0.866 & 0.9785 \\
    Unknown scan, unknown TF      & 24.75 & 0.769 & 0.9643 \\
    \bottomrule
  \end{tabular}
  \end{center}
  \vspace{0.5em}
  \begin{columns}
    \column{0.48\textwidth}
      \begin{exampleblock}{Good Generalization}
        Robust to new viewpoints, new transfer functions, and new anatomy to a reasonable extent
      \end{exampleblock}

    \column{0.48\textwidth}
      \begin{alertblock}{Identified Limit}
        Notable quality drop on \textbf{completely unseen scan + unknown TF} $\rightarrow$ a more diverse training dataset is needed
      \end{alertblock}
  \end{columns}
\end{frame}

% ==================== SECTION 6 ====================
\section{Limitations \& Future Work}

\begin{frame}{Limitations \& Future Work}
  \begin{columns}
    \column{0.5\textwidth}
      \begin{alertblock}{Current Limitations}
        \begin{enumerate}
          \item Designed for \textbf{offline} video generation (not real-time)
          \item Renderer characteristics \textbf{baked into} network weights
          \item Universal anatomical patterns may be \textbf{memorized} by the network
          \item Training data limited to \textbf{human CT scans}
        \end{enumerate}
      \end{alertblock}

    \column{0.5\textwidth}
      \begin{block}{Future Directions}
        \begin{itemize}
          \item \textbf{Real-time inference} via recurrent connections or network optimization
          \item \textbf{Adaptive sampling} guided by the denoiser
          \item Extension to other modalities: veterinary, MRI, ultrasound
          \item Cross-anatomy transfer evaluation (upper/lower body)
          \item Richer \textbf{training dataset} for broader generalization
        \end{itemize}
      \end{block}
  \end{columns}
\end{frame}

% ==================== SECTION 7 ====================
\section{Conclusion}

\begin{frame}{Conclusion}
  \begin{block}{What This Paper Achieved}
    First successful adaptation of learning-based neural denoising to medical volumetric path tracing
  \end{block}

  \vspace{0.5em}
  \begin{columns}
    \column{0.48\textwidth}
      \textbf{Key Contributions:}
      \begin{itemize}
        \item[\checkmark] \textbf{Volumetric auxiliary features}
        \item[\checkmark] \textbf{Specular loss} $L_{\text{spec}}$ for highlights
        \item[\checkmark] \textbf{Dual autoencoder} (direct + indirect)
        \item[\checkmark] \textbf{Relativistic GAN} for sharpness
        \item[\checkmark] \textbf{Temporal reprojection} for video
      \end{itemize}

    \column{0.48\textwidth}
      \begin{exampleblock}{Final Impact}
        \begin{itemize}
          \item \textbf{185$\times$} faster than converged rendering
          \item Outperforms industry-standard denoisers in volumetric context
          \item Open-source code available
        \end{itemize}
      \end{exampleblock}

      \vspace{0.3em}
      \begin{center}
        \texttt{\small github.com/nihofm/ndptmvd}
      \end{center}
  \end{columns}

  \vspace{0.7em}
  \begin{center}
    \large\textbf{Thank you for your attention!}\\
    \vspace{0.3em}
    \small Questions?
  \end{center}
\end{frame}

