% ==================== SECTION 1 ====================
\section{Introduction \& Context}

\begin{frame}{Context: Medical Visualization}
  \begin{columns}
    \column{0.55\textwidth}
      \begin{block}{Path Tracing in Medicine}
        \begin{itemize}
          \item Data from CT scanners (computed tomography)
          \item Photorealistic rendering $\rightarrow$ better perception
          \item Target users: students, patients, surgeons
          \item Applications: medical education, doctor-patient communication, surgery planning
        \end{itemize}
      \end{block}
      \vspace{0.5em}
      \begin{alertblock}{The Core Problem}
        A converged image requires \textbf{$\approx$1000 samples/pixel}\\
        $\Rightarrow$ Several \textbf{minutes per frame}, \textbf{hours for a video}
      \end{alertblock}

    \column{0.42\textwidth}
      \begin{center}
        \begin{tikzpicture}
          \draw[fill=medgray, rounded corners=5pt] (0,0) rectangle (4, 4.5);
          \node[align=center, text width=3.5cm] at (2, 3.5) {\small\textbf{1 sppx (noisy)}};
          \draw[fill=red!20, rounded corners=3pt] (0.2,2.5) rectangle (3.8, 3.2);
          \node[align=center] at (2, 2.85) {\small\textit{Heavy noise}};

          \draw[->, very thick, medblue] (2, 2.3) -- (2, 1.7);
          \node[align=center] at (2, 1.5) {\small\textbf{Neural Network}};
          \draw[->, very thick, medgreen] (2, 1.2) -- (2, 0.6);

          \draw[fill=green!20, rounded corners=3pt] (0.2,0.1) rectangle (3.8, 0.8);
          \node[align=center] at (2, 0.45) {\small\textit{Denoised image}};
        \end{tikzpicture}
      \end{center}
  \end{columns}
\end{frame}

\begin{frame}{Paper Objectives}
  \begin{block}{Research Question}
    Can we transfer neural denoising techniques developed for \emph{surface} rendering to the harder problem of \emph{medical volumetric} rendering?
  \end{block}

  \vspace{1em}
  \begin{columns}
    \column{0.48\textwidth}
      \textbf{Main Contributions:}
      \begin{enumerate}
        \item[\textcolor{medblue}{1.}] Novel \textbf{volumetric auxiliary features}
        \item[\textcolor{medblue}{2.}] \textbf{Loss function} tailored for specular highlights
        \item[\textcolor{medblue}{3.}] \textbf{Dual autoencoder} architecture
        \item[\textcolor{medblue}{4.}] \textbf{Relativistic discriminator} (GAN)
        \item[\textcolor{medblue}{5.}] \textbf{Feature reprojection} for temporal coherence
      \end{enumerate}

    \column{0.48\textwidth}
      \textbf{Key Result:}
      \begin{exampleblock}{}
        \textbf{185$\times$ speedup} over fully converged rendering, using only one rendering pass per pixel.
      \end{exampleblock}
  \end{columns}
\end{frame}

% ==================== SECTION 2 ====================
\section{Related Work}

\begin{frame}{Related Work: Hand-Crafted Filters}
  \begin{columns}
    \column{0.5\textwidth}
      \textbf{Classical Approaches}
      \begin{itemize}
        \item \textbf{À-Trous filters} with auxiliary features (depth, normals, albedo)\\
              \textit{-- Dammertz et al. 2010}
        \item \textbf{Guided filtering}\\
              \textit{-- Bauszat et al. 2011}
        \item \textbf{Non-local means}\\
              \textit{-- Rousselle et al. 2012}
        \item \textbf{SVGF} (Spatiotemporal Variance-Guided Filtering)\\
              \textit{-- Schied et al. 2017}
      \end{itemize}

    \column{0.5\textwidth}
      \textbf{Limitations}
      \begin{alertblock}{}
        \begin{itemize}
          \item Depth and normals \textbf{ill-defined} in volumetric rendering
          \item Tendency to \textbf{over-smooth} fine structures
          \item Temporal stability hard to guarantee
        \end{itemize}
      \end{alertblock}
      \vspace{0.3em}
      \begin{exampleblock}{Key Insight}
        Hand-crafted filters cannot automatically adapt to the complex nature of medical volumes
      \end{exampleblock}
  \end{columns}
\end{frame}

\begin{frame}{Related Work: Learning-Based Denoising}
  \begin{columns}
    \column{0.5\textwidth}
      \textbf{Learning-Based Approaches}
      \begin{itemize}
        \item \textbf{Kernel prediction} via MLP / CNN\\
              \textit{-- Kalantari 2015, Bako 2017}
        \item \textbf{Noise2Noise}: training without clean data\\
              \textit{-- Lehtinen et al. 2018}
        \item \textbf{Recurrent autoencoder} for temporal stability\\
              \textit{-- Chaitanya et al. 2017}
        \item \textbf{Kernel-splatting} for reconstruction fidelity\\
              \textit{-- Gharbi et al. 2019}
        \item Integrated in \textbf{OptiX} (NVIDIA) \& \textbf{OIDN} (Intel)
      \end{itemize}

    \column{0.5\textwidth}
      \textbf{Critical Gap: all of this = surfaces only}
      \begin{tikzpicture}
        \draw[fill=medgray, rounded corners=5pt] (0,0) rectangle (4.5, 3.5);
        \node[align=center, text width=4cm, font=\small] at (2.25, 3.0) {\textbf{Standard Pipeline}};
        \draw[fill=medlightblue, rounded corners=3pt] (0.2, 2.2) rectangle (4.3, 2.7);
        \node at (2.25, 2.45) {\small Depth / Normals / Albedo};
        \draw[->, thick] (2.25, 2.2) -- (2.25, 1.7);
        \draw[fill=medlightblue, rounded corners=3pt] (0.2, 1.1) rectangle (4.3, 1.7);
        \node at (2.25, 1.4) {\small CNN Denoiser};
        \draw[->, thick] (2.25, 1.1) -- (2.25, 0.6);
        \draw[fill=red!30, rounded corners=3pt] (0.2, 0.1) rectangle (4.3, 0.6);
        \node at (2.25, 0.35) {\small \textbf{Fails on medical volumes}};
      \end{tikzpicture}
  \end{columns}
\end{frame}

% ==================== SECTION 3 ====================
\section{Challenges of Volumetric Denoising}

\begin{frame}{Why Is Volumetric Different?}
  \begin{block}{3 Fundamental Challenges}
  \end{block}
  \vspace{0.5em}
  \begin{columns}
    \column{0.32\textwidth}
      \textbf{\textcolor{medblue}{Challenge 1 -- Noisy Features}}\\
      \vspace{0.3em}
      Depth and normals are \textbf{stochastic} (depend on scatter events): they are \emph{themselves} noisy and cannot reliably guide the filter as they would for surfaces.

    \column{0.32\textwidth}
      \textbf{\textcolor{medblue}{Challenge 2 -- Heterogeneity}}\\
      \vspace{0.3em}
      Medical data contains both \textbf{fuzzy, cloud-like} structures (soft tissue) and \textbf{dense} ones (bones, vessels) with sharp specular highlights that must not be blurred.

    \column{0.32\textwidth}
      \textbf{\textcolor{medblue}{Challenge 3 -- Temporal Stability}}\\
      \vspace{0.3em}
      For video generation, independently denoising each frame produces highly \textbf{distracting flickering} artifacts even when individual frames are acceptable.
  \end{columns}

  \vspace{1em}
  \begin{alertblock}{Consequence}
    Applying existing denoisers (OptiX, OIDN) directly gives poor results: PSNR $\approx 17$--$25$ dB vs.\ $>30$ dB with the proposed method.
  \end{alertblock}
\end{frame}

\begin{frame}{The Volumetric Path Tracing Pipeline}
  \begin{block}{Base: Cinematic Rendering (Comaniciu et al. 2016)}
    Volumetric path tracing on a 3D voxel grid with an RGBA transfer function
  \end{block}

  \vspace{0.5em}
  \begin{tikzpicture}[scale=0.85, every node/.style={font=\small}]
    \node[draw, fill=medlightblue, rounded corners, minimum width=2cm, minimum height=0.8cm] (ray) at (0,0) {Ray cast};
    \node[draw, fill=medlightblue, rounded corners, minimum width=2.2cm, minimum height=0.8cm] (march) at (3.5,0) {Ray marching};
    \node[draw, fill=medlightblue, rounded corners, minimum width=2.5cm, minimum height=0.8cm] (scatter) at (7.2,0) {Scatter event};
    \node[draw, fill=medlightblue, rounded corners, minimum width=2.2cm, minimum height=0.8cm] (env) at (11,0) {Env. map sample};

    \draw[->, thick, medblue] (ray) -- (march);
    \draw[->, thick, medblue] (march) -- (scatter);
    \draw[->, thick, medblue] (scatter) -- (env);

    \node[align=center, text width=2.5cm, text=medred] at (3.5, -1.2) {optical thickness tracked};
    \node[align=center, text width=3cm, text=medred] at (7.2, -1.2) {+Phong term if surface-like};
    \node[align=center, text width=3cm, text=medred] at (11, -1.2) {\textbf{1000 sppx} for convergence};
  \end{tikzpicture}

  \vspace{0.8em}
  \begin{columns}
    \column{0.48\textwidth}
      \begin{exampleblock}{Advantage}
        Hybrid volumetric + surface handling $\rightarrow$ naturalistic rendering
      \end{exampleblock}

    \column{0.48\textwidth}
      \begin{alertblock}{Drawback}
        Noise is very high at low sample counts (isotropic phase function, absorption after $N$ bounces)
      \end{alertblock}
  \end{columns}
\end{frame}

% ==================== SECTION 4 ====================
\section{Proposed Solutions}

\begin{frame}{Solution 1 -- Volumetric Auxiliary Features}
  \begin{columns}
    \column{0.52\textwidth}
      \textbf{Primary Features} (1\textsuperscript{st} scatter event)
      \begin{itemize}
        \item Position (model space)
        \item Normal (gradient at scatter point)
        \item Albedo (transfer function value)
        \item \textbf{Volumetric characteristics:}\\
              gradient magnitude, optical thickness, extinction coefficient
      \end{itemize}

      \vspace{0.5em}
      \textbf{Secondary Features} (2\textsuperscript{nd} bounce)
      \begin{itemize}
        \item Color after 1\textsuperscript{st} surface scatter event
        \item Albedo at 2\textsuperscript{nd} scatter point
        \item Volumetric characteristics (1\textsuperscript{st} $\to$ 2\textsuperscript{nd} bounce)
      \end{itemize}

    \column{0.45\textwidth}
      \begin{block}{Why only 1 sample?}
        \begin{itemize}
          \item Keeps rendering times minimal
          \item Averaging multiple samples \textbf{degrades} position and normal features (stochastic averaging)
        \end{itemize}
      \end{block}

      \begin{alertblock}{Key Challenge}
        All these features are \textbf{themselves noisy} $\Rightarrow$ dedicated network architecture required
      \end{alertblock}
  \end{columns}
\end{frame}

\begin{frame}{Solution 2 -- Adapted Loss Function}
  \begin{block}{Reconstruction Loss}
    \vspace{0.3em}
    \[
      L = 0.8 \cdot L_1 + 0.1 \cdot L_{\text{hfen}} + 0.1 \cdot L_{\text{spec}}
    \]
    \vspace{-0.3em}
  \end{block}

  \begin{columns}
    \column{0.5\textwidth}
      \textbf{Components:}
      \begin{itemize}
        \item $L_1$: absolute pixel-wise error
        \item $L_{\text{hfen}}$: \textit{High Frequency Error Norm}\\
              $\rightarrow$ compares image \textbf{gradients} ($\sigma=1.5$)
        \item $L_{\text{spec}}$: \textbf{specular highlight} term (novel)
        \[
          L_{\text{spec}} = \frac{1}{N}\sum_i \left|\max(0, x_i - \mu_{x_i}) - \max(0, y_i - \mu_{y_i})\right|
        \]
      \end{itemize}

    \column{0.46\textwidth}
      \begin{exampleblock}{Role of $L_{\text{spec}}$}
        \begin{itemize}
          \item Isolates highlights by subtracting local mean ($11\times11$ neighborhood)
          \item Compensates severe undersampling of specular reflections (stochastic diffuse/specular alternation)
          \item RMSE: \textbf{0.0279 $\to$ 0.0247} with $L_{\text{spec}}$
        \end{itemize}
      \end{exampleblock}
  \end{columns}
\end{frame}

\begin{frame}{Solution 3 -- Dual Autoencoder Network}
  \begin{block}{Principle: Divide and Conquer}
    Secondary features (very noisy) degrade performance when processed naively in a single network
  \end{block}

  \vspace{0.5em}
  \begin{columns}
    \column{0.52\textwidth}
      \begin{tikzpicture}[scale=0.8, font=\small]
        % Primary branch
        \draw[fill=blue!15, rounded corners=4pt] (0, 2.5) rectangle (2.5, 3.2);
        \node at (1.25, 2.85) {\textbf{Primary Network}};
        \draw[fill=blue!10, rounded corners=2pt] (0, 1.8) rectangle (2.5, 2.5);
        \node at (1.25, 2.15) {U-Net (primary feats.)};
        \node[align=center, font=\tiny] at (1.25, 1.5) {Direct illumination\\high-frequency};

        % Secondary branch
        \draw[fill=green!15, rounded corners=4pt] (3.5, 2.5) rectangle (6, 3.2);
        \node at (4.75, 2.85) {\textbf{Secondary Network}};
        \draw[fill=green!10, rounded corners=2pt] (3.5, 1.8) rectangle (6, 2.5);
        \node at (4.75, 2.15) {U-Net (secondary feats.)};
        \node[align=center, font=\tiny] at (4.75, 1.5) {Indirect illumination\\low-frequency};

        % Join
        \draw[->, thick] (2.5, 2.15) -- (3.5, 2.15);
        \node[draw, fill=orange!30, rounded corners=3pt, minimum height=0.6cm, minimum width=1.5cm] at (3, 0.6) {Merge};
        \draw[->, thick] (1.25, 1.3) -- (1.25, 0.6) -- (2.25, 0.6);
        \draw[->, thick] (4.75, 1.3) -- (4.75, 0.6) -- (3.75, 0.6);
        \draw[->, thick] (3, 0.3) -- (3, -0.2);
        \node at (3, -0.45) {\textbf{Denoised output}};
      \end{tikzpicture}

    \column{0.45\textwidth}
      \textbf{How it works:}
      \begin{itemize}
        \item Network 1: high-frequency direct lighting via primary features
        \item Network 2: low-frequency indirect lighting via secondary features \textbf{+ output of Network 1}
        \item Combined via a transposed convolution layer
      \end{itemize}

      \begin{exampleblock}{Gain}
        Enables exploitation of very noisy secondary features that would harm a single network
      \end{exampleblock}
  \end{columns}
\end{frame}

\begin{frame}{Solution 4 -- Relativistic Discriminator (GAN)}
  \begin{columns}
    \column{0.5\textwidth}
      \begin{block}{Motivation}
        Static losses ($L_1$, HFEN) tend to produce blurry outputs. A discriminator forces the generation of \textbf{visually sharp, plausible details}.
      \end{block}

      \vspace{0.5em}
      \textbf{Architecture:}
      \begin{itemize}
        \item 5 convolutional blocks (LeakyReLU + spatial dropout + batch norm)
        \item $3\times3$ convolutions, stride 2, $32 \cdot 2^i$ feature maps
        \item Average pooling as final layer
      \end{itemize}

      \textbf{Combined loss:}
      \[
        L_{\text{total}} = 0.6 \cdot L_d + 0.4 \cdot L_r
      \]

    \column{0.46\textwidth}
      \begin{exampleblock}{Relativistic Discriminator}
        Estimates the probability that \emph{real} data is more realistic than \emph{generated} data $\rightarrow$ fewer updates needed, higher quality results.
      \end{exampleblock}

      \begin{alertblock}{Medical Nuance}
        GANs may introduce details \textbf{absent from ground truth} -- acceptable here since the use case is \textbf{visualization} (patients, students), not clinical diagnosis.
      \end{alertblock}
  \end{columns}
\end{frame}

\begin{frame}{Solution 5 -- Feature Reprojection Network}
  \begin{block}{Goal: Temporal Coherence Without Extra Rendering Cost}
    Reuse samples from adjacent frames via reprojection
  \end{block}

  \vspace{0.5em}
  \begin{columns}
    \column{0.5\textwidth}
      \textbf{How it works:}
      \begin{itemize}
        \item Reprojection based on distance to 1\textsuperscript{st} scatter event
        \item 3 frames considered: $t-1$, $t$, $t+1$
        \item 8 small autoencoders (one per feature channel + color) to merge the 3 reprojected versions
        \item Trained \textit{end-to-end} without locking encoders
      \end{itemize}

    \column{0.46\textwidth}
      \textbf{Volumetric reprojection challenges:}
      \begin{alertblock}{}
        \begin{itemize}
          \item Stochastic depth $\rightarrow$ jitter even with static camera
          \item More occlusion/disocclusion artifacts than surfaces
          \item Artifacts amplified compared to the surface case
        \end{itemize}
      \end{alertblock}

      \begin{exampleblock}{Result}
        Best SSIM and temporal stability of all tested architectures
      \end{exampleblock}
  \end{columns}
\end{frame}

% ==================== SECTION 5 ====================
\section{Results \& Evaluation}

\begin{frame}{Experimental Setup}
  \begin{columns}
    \column{0.48\textwidth}
      \textbf{Data:}
      \begin{itemize}
        \item \textbf{Train:} $\approx$3000 frames, CT scans of male patients, varied transfer functions and env.\ maps
        \item \textbf{Test:} 300 frames, CT scan of a female patient \textbf{unseen during training}
        \item Resolution: $1024 \times 1024$ pixels
        \item GPU: GTX 1070 (consumer-grade)
      \end{itemize}

      \vspace{0.5em}
      \textbf{Metrics:}
      \begin{itemize}
        \item \textbf{PSNR} (peak signal-to-noise ratio)
        \item \textbf{SSIM} (structural similarity index)
        \item \textbf{Temporal stability} ($1 - L_t$)
      \end{itemize}

    \column{0.48\textwidth}
      \textbf{Evaluated Configurations:}
      \begin{enumerate}
        \item \textit{Color only} (internal baseline)
        \item \textit{All features} (full feature set)
        \item \textit{Dual} (dual autoencoder)
        \item \textit{GAN} (+ discriminator)
        \item \textit{Reprojection} (+ temporal)
      \end{enumerate}

      \vspace{0.3em}
      \textbf{External Baselines:}
      \begin{itemize}
        \item OptiX 6.5 (NVIDIA)
        \item Open Image Denoise 1.2 (Intel)
      \end{itemize}
  \end{columns}
\end{frame}

\begin{frame}{Quantitative Results}
  \begin{center}
  \begin{tabular}{lcccc}
    \toprule
    \textbf{Method} & \textbf{PSNR} & \textbf{SSIM} & \textbf{Temp.\ Stab.} & \textbf{t/frame} \\
    \midrule
    OptiX (NVIDIA)  & 24.72 & 0.806 & 0.9517 & -- \\
    OIDN (Intel)    & 17.40 & 0.768 & 0.9727 & -- \\
    \midrule
    Color only      & $\sim$29   & 0.87 & 0.979 & 124 ms \\
    All features    & $\sim$31   & 0.89 & 0.981 & 131 ms \\
    Dual            & $\sim$31.5 & 0.90 & 0.982 & 268 ms \\
    GAN             & $\sim$32   & 0.91 & 0.982 & 268 ms \\
    \textbf{Reprojection} & $\sim$28.5 & \textbf{0.92} & \textbf{0.988} & 502 ms \\
    \bottomrule
  \end{tabular}
  \end{center}

  \vspace{0.5em}
  \begin{columns}
    \column{0.48\textwidth}
      \begin{exampleblock}{Strengths}
        \begin{itemize}
          \item All variants outperform industry baselines
          \item Reprojection maximizes SSIM and stability
        \end{itemize}
      \end{exampleblock}

    \column{0.48\textwidth}
      \begin{alertblock}{Reprojection PSNR Nuance}
        Lower PSNR due to \textbf{color bleeding} between frames (changing transfer functions), but visually superior in video sequences
      \end{alertblock}
  \end{columns}
\end{frame}

\begin{frame}{Rendering Time -- \textbf{185$\times$ Speedup}}
  \begin{center}
  \begin{tabular}{lrr}
    \toprule
    \textbf{Pipeline} & \textbf{300 frames} & \textbf{Per frame} \\
    \midrule
    Ground truth (1024 sppx) & 12h 6min & $\sim$2.4 min \\
    \midrule
    Render at 1 sppx          & 1 min 24 s & 0.28 s \\
    + Reprojection denoising  & 2 min 31 s & 0.50 s \\
    \midrule
    \textbf{Full denoised pipeline} & \textbf{3 min 55 s} & \textbf{0.78 s} \\
    \bottomrule
  \end{tabular}
  \end{center}

  \vspace{0.8em}
  \begin{columns}
    \column{0.48\textwidth}
      \begin{exampleblock}{Hardware Context}
        Measured on a consumer \textbf{GTX 1070}, no tensor cores, fp32 precision -- modern GPUs would yield additional speedup
      \end{exampleblock}

    \column{0.48\textwidth}
      \begin{block}{Training Cost}
        1000 full dataset iterations; \textbf{1 to 5 days} depending on architecture complexity
      \end{block}
  \end{columns}
\end{frame}

\begin{frame}{Generalization}
  \begin{center}
  \begin{tabular}{lccc}
    \toprule
    \textbf{Scenario} & \textbf{PSNR} & \textbf{SSIM} & \textbf{Stab.} \\
    \midrule
    Training set                  & 32.98 & 0.880 & 0.9824 \\
    Known scan, known TF          & 30.50 & 0.915 & 0.9854 \\
    Known scan, unknown TF        & 28.66 & 0.840 & 0.9761 \\
    Known scan, uniform density   & 32.05 & 0.907 & 0.9868 \\
    Unknown scan, known TF        & 27.10 & 0.866 & 0.9785 \\
    Unknown scan, unknown TF      & 24.75 & 0.769 & 0.9643 \\
    \bottomrule
  \end{tabular}
  \end{center}
  \vspace{0.5em}
  \begin{columns}
    \column{0.48\textwidth}
      \begin{exampleblock}{Good Generalization}
        Robust to new viewpoints, new transfer functions, and new anatomy to a reasonable extent
      \end{exampleblock}

    \column{0.48\textwidth}
      \begin{alertblock}{Identified Limit}
        Notable quality drop on \textbf{completely unseen scan + unknown TF} $\rightarrow$ a more diverse training dataset is needed
      \end{alertblock}
  \end{columns}
\end{frame}

% ==================== SECTION 6 ====================
\section{Limitations \& Future Work}

\begin{frame}{Limitations \& Future Work}
  \begin{columns}
    \column{0.5\textwidth}
      \begin{alertblock}{Current Limitations}
        \begin{enumerate}
          \item Designed for \textbf{offline} video generation (not real-time)
          \item Renderer characteristics \textbf{baked into} network weights
          \item Universal anatomical patterns may be \textbf{memorized} by the network
          \item Training data limited to \textbf{human CT scans}
        \end{enumerate}
      \end{alertblock}

    \column{0.5\textwidth}
      \begin{block}{Future Directions}
        \begin{itemize}
          \item \textbf{Real-time inference} via recurrent connections or network optimization
          \item \textbf{Adaptive sampling} guided by the denoiser
          \item Extension to other modalities: veterinary, MRI, ultrasound
          \item Cross-anatomy transfer evaluation (upper/lower body)
          \item Richer \textbf{training dataset} for broader generalization
        \end{itemize}
      \end{block}
  \end{columns}
\end{frame}

% ==================== SECTION 7 ====================
\section{Conclusion}

\begin{frame}{Conclusion}
  \begin{block}{What This Paper Achieved}
    First successful adaptation of learning-based neural denoising to medical volumetric path tracing
  \end{block}

  \vspace{0.5em}
  \begin{columns}
    \column{0.48\textwidth}
      \textbf{Key Contributions:}
      \begin{itemize}
        \item[\checkmark] \textbf{Volumetric auxiliary features}
        \item[\checkmark] \textbf{Specular loss} $L_{\text{spec}}$ for highlights
        \item[\checkmark] \textbf{Dual autoencoder} (direct + indirect)
        \item[\checkmark] \textbf{Relativistic GAN} for sharpness
        \item[\checkmark] \textbf{Temporal reprojection} for video
      \end{itemize}

    \column{0.48\textwidth}
      \begin{exampleblock}{Final Impact}
        \begin{itemize}
          \item \textbf{185$\times$} faster than converged rendering
          \item Outperforms industry-standard denoisers in volumetric context
          \item Open-source code available
        \end{itemize}
      \end{exampleblock}

      \vspace{0.3em}
      \begin{center}
        \texttt{\small github.com/nihofm/ndptmvd}
      \end{center}
  \end{columns}

  \vspace{0.7em}
  \begin{center}
    \large\textbf{Thank you for your attention!}\\
    \vspace{0.3em}
    \small Questions?
  \end{center}
\end{frame}

% ---- Backup slide ----
\begin{frame}[noframenumbering]{Reference}
  \small
  \textbf{Paper:} Nikolai Hofmann, Jana Martschinke, Klaus Engel, Marc Stamminger.\\
  ``Neural Denoising for Path Tracing of Medical Volumetric Data''\\
  \textit{Proc. ACM Comput. Graph. Interact. Tech.}, Vol. 3, No. 2, Article 13, August 2020.\\
  \texttt{https://doi.org/10.1145/3406181}

  \vspace{1em}
  \textbf{Code:} \texttt{https://github.com/nihofm/ndptmvd}

  \vspace{1em}
  \textbf{Affiliations:}\\
  University of Erlangen-Nuremberg -- Visual Computing Group\\
  Siemens Healthineers -- Klaus Engel
\end{frame}

\end{document}
