				prop_sum = mesoSubArray[curMeso].rxnProp[curRxn];
				rand_prop = generateUniform()*mesoSubArray[curMeso].totalProp;
				while (prop_sum < rand_prop)
				{
					prop_sum += mesoSubArray[curMeso].rxnProp[++curRxn];
