# ============================================================
# STEP 1: actor.h — replace scalar energyCostActive/energyHarvestActive
#         with per-mol-type arrays + add energy log fields
# ============================================================
with open('/home/claude/AcCoRD_energy/src/actor.h', 'r') as f:
    h = f.read()

# 1a — Replace scalar fields in spec struct with arrays
old = '''	// Active energy cost per event:
	//   - For active actors: cost per molecule emission (transmission)
	//   - For passive actors: cost per molecule detection observation
	double energyCostActive;

	// Passive energy harvesting rate (energy units per second, always on)
	double energyHarvestPassive;

	// Active energy gain per event (same event types as energyCostActive)
	double energyHarvestActive;
};'''

new = '''	// Active energy cost per event — ARRAY, one value per molecule type.
	//   - For active actors  : cost per SYMBOL EMISSION of that molecule type
	//   - For passive actors : cost per MOLECULE DETECTED of that molecule type
	// This allows e.g. detection (mol type 0) to cost more than gossip (mol type 1).
	// Allocated at runtime with length NUM_MOL_TYPES.
	// NULL if bEnergyEnabled == false.
	double * energyCostPerMolType;

	// Passive energy harvesting rate (energy units per second, always on)
	double energyHarvestPassive;

	// Active energy harvest per event — ARRAY, one value per molecule type.
	// Allocated at runtime with length NUM_MOL_TYPES.
	// NULL if bEnergyEnabled == false.
	double * energyHarvestPerMolType;
};'''

if old in h:
    h = h.replace(old, new, 1)
    print("actor.h STEP 1a OK")
else:
    print("actor.h STEP 1a FAILED")

# 1b — Add energy log fields to runtime struct actorStruct3D
old2 = '''	// Time of the last energy update (used to compute passive drain/harvest dt)
	double lastEnergyUpdateTime;

	// FUTURE MEMBERS (POTENTIAL)'''

new2 = '''	// Time of the last energy update (used to compute passive drain/harvest dt)
	double lastEnergyUpdateTime;

	/*
